const countEl = document.getElementById('count');
const incrementBtn = document.getElementById('increment');
const decrementBtn = document.getElementById('decrement');
const resetBtn = document.getElementById('reset');

let count = 0;

function updateDisplay() {
  countEl.textContent = count;
  countEl.classList.remove('positive', 'negative');
  if (count > 0) {
    countEl.classList.add('positive');
  } else if (count < 0) {
    countEl.classList.add('negative');
  }
}

incrementBtn.addEventListener('click', () => {
  count++;
  updateDisplay();
});

decrementBtn.addEventListener('click', () => {
  count--;
  updateDisplay();
});

resetBtn.addEventListener('click', () => {
  count = 0;
  updateDisplay();
});

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', sans-serif;
  background-color: #FAFAF8;
  color: #1a1a1a;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

.container {
  max-width: 1100px;
  width: 100%;
  padding: 24px;
}

.card {
  background: #ffffff;
  border: 1px solid #E5E7EB;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
  border-radius: 12px;
  padding: 64px 48px;
  max-width: 420px;
  margin: 0 auto;
  text-align: center;
}

h1 {
  font-size: 1.25rem;
  font-weight: 500;
  color: #6B7280;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 32px;
}

.count {
  font-size: 5rem;
  font-weight: 700;
  line-height: 1;
  margin-bottom: 48px;
  color: #1a1a1a;
  transition: color 0.2s ease;
}

.count.positive {
  color: #4A7C6F;
}

.count.negative {
  color: #C4553D;
}

.buttons {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 500;
  border: none;
  border-radius: 8px;
  padding: 12px 24px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
}

.btn:active {
  transform: scale(0.96);
}

.btn-increment {
  background-color: #4A7C6F;
  color: #ffffff;
  font-size: 1.5rem;
  padding: 12px 32px;
}

.btn-increment:hover {
  background-color: #3D6B5F;
}

.btn-decrement {
  background-color: #C4553D;
  color: #ffffff;
  font-size: 1.5rem;
  padding: 12px 32px;
}

.btn-decrement:hover {
  background-color: #A8452F;
}

.btn-reset {
  background-color: transparent;
  color: #6B7280;
  border: 1px solid #E5E7EB;
}

.btn-reset:hover {
  background-color: #F3F4F6;
}

@media (max-width: 480px) {
  .card {
    padding: 48px 24px;
  }

  .count {
    font-size: 4rem;
  }
}
